using System.Net;
using System.Net.Http.Headers;
using System.Text.Json;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Retroscope.Integration.Tests.Blobs;
using Retroscope.Server.Hosting;

namespace Retroscope.Integration.Tests.Hosting;

// UX13: MUSIC_FILE names a deploy-time audio file that /media/timer-music streams with range support. Every file
// here is a few generated bytes that only look like audio; no real track is ever part of the repository.
[Trait("Category", "Hosting")]
public sealed class TimerMusicTests : IDisposable {
    private static readonly byte[] Mp3 = [.. "ID3"u8, 4, 0, 0, 0, 0, 0, 0, .. Enumerable.Range(0, 1000).Select(x => (byte)x)];

    private readonly DirectoryInfo _dir = Directory.CreateTempSubdirectory("rs-music-");

    public void Dispose() => _dir.Delete(recursive: true);

    [Fact]
    public async Task Without_music_file_the_route_is_404_and_the_boot_has_no_flag() {
        await using var app = await TestApp.StartAsync();

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
        Assert.False((await BootAsync(app, "/retro/ABCDEFGHJK")).TryGetProperty("timerMusic", out _));
    }

    [Fact]
    public async Task A_configured_track_is_streamed_with_its_type_validators_and_cache_policy() {
        await using var app = await StartAsync(Write("track.mp3", Mp3));

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal(Mp3, await response.Content.ReadAsByteArrayAsync(TestContext.Current.CancellationToken));
        Assert.Equal("audio/mpeg", response.Content.Headers.ContentType?.ToString());
        Assert.Equal(TimerMusic.CacheControl, response.Headers.CacheControl?.ToString());
        Assert.Equal("bytes", Assert.Single(response.Headers.AcceptRanges));
        Assert.NotNull(response.Headers.ETag);
        Assert.False(response.Headers.ETag!.IsWeak);
        Assert.NotNull(response.Content.Headers.LastModified);
        Assert.Equal("nosniff", string.Join(",", response.Headers.GetValues("X-Content-Type-Options")));
    }

    [Fact]
    public async Task A_range_request_gets_206_with_just_those_bytes() {
        await using var app = await StartAsync(Write("track.mp3", Mp3));
        using var request = new HttpRequestMessage(HttpMethod.Get, TimerMusic.Path);
        request.Headers.Range = new RangeHeaderValue(100, 199);

        using var response = await app.Client.SendAsync(request, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.PartialContent, response.StatusCode);
        Assert.Equal(Mp3[100..200], await response.Content.ReadAsByteArrayAsync(TestContext.Current.CancellationToken));
        Assert.Equal($"bytes 100-199/{Mp3.Length}", response.Content.Headers.ContentRange?.ToString());
        Assert.Equal("audio/mpeg", response.Content.Headers.ContentType?.ToString());
    }

    [Fact]
    public async Task A_range_past_the_end_is_416_and_a_matching_etag_is_304() {
        await using var app = await StartAsync(Write("track.mp3", Mp3));
        using var first = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        using var past = new HttpRequestMessage(HttpMethod.Get, TimerMusic.Path);
        past.Headers.Range = new RangeHeaderValue(Mp3.Length + 10, null);
        using var pastResponse = await app.Client.SendAsync(past, TestContext.Current.CancellationToken);
        using var again = new HttpRequestMessage(HttpMethod.Get, TimerMusic.Path);
        again.Headers.IfNoneMatch.Add(first.Headers.ETag!);
        using var againResponse = await app.Client.SendAsync(again, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.RequestedRangeNotSatisfiable, pastResponse.StatusCode);
        Assert.Equal(HttpStatusCode.NotModified, againResponse.StatusCode);
    }

    [Theory]
    [InlineData("track.ogg", "audio/ogg")]
    [InlineData("track.oga", "audio/ogg")]
    [InlineData("track.m4a", "audio/mp4")]
    public async Task Ogg_and_m4a_tracks_get_their_own_content_type(string name, string contentType) {
        byte[] bytes = contentType == "audio/ogg" ? [.. "OggS"u8, 0, 2, 0, 0] : [0, 0, 0, 24, .. "ftypM4A "u8];
        await using var app = await StartAsync(Write(name, bytes));

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal(contentType, response.Content.Headers.ContentType?.ToString());
    }

    [Fact]
    public async Task The_boot_of_a_retro_board_says_a_track_exists_and_other_routes_do_not() {
        await using var app = await StartAsync(Write("track.mp3", Mp3));

        Assert.True((await BootAsync(app, "/retro/ABCDEFGHJK")).GetProperty("timerMusic").GetBoolean());
        Assert.False((await BootAsync(app, "/poker/ABCDEFGHJK")).TryGetProperty("timerMusic", out _));
    }

    public static TheoryData<string, byte[], string> InvalidFiles => new() {
        { "track.wav", [.. "RIFF"u8, 0, 0, 0, 0], ".mp3, .ogg, .oga or .m4a" },
        { "track.mp3", [.. "<html>"u8], "does not start like audio/mpeg" },
        { "track.ogg", [.. "ID3"u8, 4, 0], "does not start like audio/ogg" },
        { "empty.mp3", [], "between 1 byte and 32 MiB" },
    };

    [Theory]
    [MemberData(nameof(InvalidFiles))]
    public async Task An_invalid_file_turns_the_route_off_with_a_warning(string name, byte[] bytes, string reason) {
        var logs = new CapturingLoggerProvider();
        await using var app = await StartAsync(Write(name, bytes), logs);

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
        Assert.False((await BootAsync(app, "/retro/ABCDEFGHJK")).TryGetProperty("timerMusic", out _));
        var warning = Assert.Single(logs.Entries, x => x.Level == LogLevel.Warning && x.Message.StartsWith("Timer music is off", StringComparison.Ordinal));
        Assert.Contains(reason, warning.Message, StringComparison.Ordinal);
        Assert.DoesNotContain(_dir.FullName, warning.Message, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("missing.mp3", "does not exist")]
    [InlineData("relative/track.mp3", "absolute path")]
    public async Task A_missing_or_relative_path_turns_the_route_off_with_a_warning(string name, string reason) {
        var logs = new CapturingLoggerProvider();
        var path = name.StartsWith("relative", StringComparison.Ordinal) ? name : Path.Combine(_dir.FullName, name);
        await using var app = await StartAsync(path, logs);

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
        Assert.Contains(logs.Entries, x => x.Level == LogLevel.Warning && x.Message.Contains(reason, StringComparison.Ordinal));
    }

    [Fact]
    public async Task A_file_over_the_cap_is_refused() {
        var path = Path.Combine(_dir.FullName, "large.mp3");
        await using (var stream = File.Create(path)) {
            await stream.WriteAsync("ID3"u8.ToArray(), TestContext.Current.CancellationToken);
            stream.SetLength(TimerMusic.MaxBytes + 1);
        }
        var logs = new CapturingLoggerProvider();
        await using var app = await StartAsync(path, logs);

        using var response = await app.Client.GetAsync(TimerMusic.Path, TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
        Assert.Contains(logs.Entries, x => x.Level == LogLevel.Warning && x.Message.Contains("32 MiB", StringComparison.Ordinal));
    }

    [Fact]
    public async Task The_route_is_public_and_limited_per_ip() {
        await using var app = await StartAsync(Write("track.mp3", Mp3));

        for (var i = 0; i < 120; i++) {
            using var ok = await app.Client.SendAsync(TestApp.Get(TimerMusic.Path, "198.51.100.7"), TestContext.Current.CancellationToken);
            Assert.Equal(HttpStatusCode.OK, ok.StatusCode);
        }
        using var limited = await app.Client.SendAsync(TestApp.Get(TimerMusic.Path, "198.51.100.7"), TestContext.Current.CancellationToken);
        using var other = await app.Client.SendAsync(TestApp.Get(TimerMusic.Path, "198.51.100.8"), TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.TooManyRequests, limited.StatusCode);
        Assert.Equal(HttpStatusCode.OK, other.StatusCode);
    }

    private string Write(string name, byte[] bytes) {
        var path = Path.Combine(_dir.FullName, name);
        File.WriteAllBytes(path, bytes);
        return path;
    }

    private static Task<TestApp> StartAsync(string musicFile, CapturingLoggerProvider? logs = null) =>
        TestApp.StartAsync(
            new() { ["MUSIC_FILE"] = musicFile },
            services => {
                if (logs is not null) {
                    services.AddLogging(logging => logging.AddProvider(logs));
                }
            });

    private static async Task<JsonElement> BootAsync(TestApp app, string path) {
        var json = await app.Client.GetStringAsync(
            new Uri("/api/boot?path=" + Uri.EscapeDataString(path), UriKind.Relative),
            TestContext.Current.CancellationToken);
        return JsonDocument.Parse(json).RootElement.Clone();
    }
}
